/* prog36_pascal_triangle – reconstructed from the analysed binary
 *
 * Behaviour (identical to the original program):
 *
 *   • No command‑line argument          → prints "NO_INPUT"
 *   • Argument not a pure decimal number → prints "BAD_INPUT"
 *   • Negative number                    → prints "BAD_INPUT"
 *   • Zero                               → prints "EMPTY"
 *   • Number > 60                        → prints "OUT_OF_RANGE"
 *   • Otherwise (1 … 60)                → prints Pascal's triangle
 *                                          with the given number of rows.
 *                                          Each value is printed with %lld,
 *                                          a single space follows **every**
 *                                          value (including the last one),
 *                                          and each row ends with a newline.
 *
 * The implementation follows the logic discovered in the decompiled
 * state‑machine: parsing, validation, and an in‑place generation of the
 * triangle using 64‑bit signed integers.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* ---------- input handling ---------------------------------------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &endptr, 10);

    /* strtoll must consume the whole string and not set an error */
    if (endptr == argv[1] || *endptr != '\0' || errno != 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- Pascal triangle generation ---------------------------- */
    /* The original binary kept the current row in a fixed‑size array
       (61 elements) and updated it in‑place from right to left.  We do the
       same, using a static buffer that never exceeds 61 elements. */
    long long row[61] = {0};

    for (long long r = 0; r < n; ++r) {
        /* set the right‑most element of the new row to 1 */
        row[r] = 1;

        /* update interior elements from right to left:
           row[j] = row[j] + row[j-1]   for j = r‑1 … 1 */
        for (long long j = r - 1; j > 0; --j) {
            row[j] = row[j] + row[j - 1];
        }
        /* row[0] stays 1 */

        /* ---------- printing the current row ------------------------ */
        for (long long c = 0; c <= r; ++c) {
            printf("%lld ", row[c]);   /* space after every number */
        }
        putchar('\n');
    }

    return 0;
}
